; ?>" maxlength="255"><?php endif; ?><?php if (! empty($field['help'])): ?><div class="form-hint"><?php echo html_escape($field['help']); ?></div><?php endif; ?></div><?php endforeach; ?></div></div><div class="card-footer text-end"><button class="btn btn-primary" type="submit">Lưu cấu hình</button></div></form></div></div>
